B.cf_=new A.nd(B.b4H,B.b7z,B.aVV,B.aY1,B.aXM,B.aVO,"\uac19\uc740 \ub9d0 \ud574\ub3c4 \uc22b\uc790\ub294 \uc548 \ubc14\ub00c\uc5b4. \ub2e4\ub978 \uadfc\uac70 \uc788\uc5b4?","\uc9c0\uae08\uae4c\uc9c0\ub294 \uc190\uc2e4\uc774\uc57c. \ubb34\uc2a8 \uc218\uc775\uc778\uc9c0 \ud655\uc778\ud560 \uac78 \ubcf4\uc5ec \uc918.","\uc9c0\uae08\uae4c\uc9c0\ub294 \uc218\uc775\uc774\uc57c. \ub2e4\ub978 \uc190\uc2e4\uc774\uba74 \uc5b4\ub514\uc11c \ub09c \uac74\uc9c0 \ubcf4\uc5ec \uc918.","\uc624\ub298\uc740 \uc190\ud574\uc57c. \ubc88 \uac74 \ub2e4\ub978 \ub0a0 \uc598\uae30\uc57c?","\uc624\ub298\uc740 \ubc8c\uc5c8\uc5b4. \uc804\uccb4 \uc190\uc2e4\uc744 \ub9d0\ud55c \uac70\uba74 \uadf8\ub807\uac8c \ub9d0\ud574.")
B.b9l=s(["\uc751, \uc77d\uc5c8\uc5b4.","\ub124 \ub9d0\uc758 \ub290\ub08c\uc740 \uc54c\uaca0\uc5b4.","\uc194\uc9c1\ud558\uac8c \ub9d0\ud574 \uc918\uc11c \uace0\ub9c8\uc6cc.","\ucc9c\ucc9c\ud788 \uc77d\uc5b4 \ubd24\uc5b4.","\uadf8 \ub9c8\uc74c\uc744 \uac00\ubccd\uac8c \ub118\uae30\uace0 \uc2f6\uc9c0 \uc54a\uc544.","\ub124\uac00 \ub290\ub080 \uacb0\uc744 \uc774\uc81c\ub294 \uc54c\uc544."],t.s)
B.aW8=s(["\uc544\uc9c1 \uacb0\uacfc\ub3c4 \uc548 \ub098\uc654\ub294\ub370 \ub9c8\uc74c\ubd80\ud130 \ub2ec\ub9ac\uc9c4 \ub9d0\uc790.","\uc624\ub298\uc740 \uc7a5 \uc26c\uc796\uc544. \uc22b\uc790\ub3c4 \uc7a0\uae50 \ub0b4\ub824\ub193\uc790.","\uc624\ub298\uc740 \uc870\uc6a9\ud588\ub124. \uc774\ub7f0 \ub0a0\ub3c4 \uc788\ub294 \uac70\uc9c0.","\uc624\ub298\ub3c4 \ubc8c\uc5c8\uace0 \uc9c0\uae08\uae4c\uc9c0\ub3c4 \ud50c\ub7ec\uc2a4\ub124. \uc798\ub410\ub2e4.","\uc624\ub298\uc740 \uc62c\ub790\uc9c0\ub9cc \uc544\uc9c1 \ubcf8\uc804 \uc544\ub798\uc57c. \uadf8\ub798\ub3c4 \uc870\uae08 \ub098\uc544\uc84c\ub124.","\uc624\ub298\uc740 \ub0b4\ub824\ub3c4 \uc9c0\uae08\uae4c\uc9c0 \ubc88 \uac74 \ub0a8\uc544 \uc788\ub124.","\uc624\ub298\ub3c4 \uc783\uc5c8\uace0 \uc544\uc9c1 \ubcf8\uc804 \uc544\ub798\ub124. \ud63c\uc790 \ubc84\ud2f0\uc9c4 \ub9c8."],t.s)
B.b9C=s(["\ub124\uac00 \uc88b\uc544\ud55c \uac70\ub791 \uc0ac\ub78c\ub4e4\uc774 \uacc4\uc18d \uc0ac\ub294 \uac74 \ub2e4\ub97c \uc218 \uc788\uc5b4.","\uc18d\uc0c1\ud558\uaca0\uc9c0\ub9cc, \uc4f0\ub294 \uc0ac\ub78c\ub4e4\uc740 \uc9c4\uc9dc \ud3b8\ud588\ub294\uc9c0 \ub2e4\uc2dc \ubcf4\uc790."],t.s)
B.b_W=s(["\uc798\ub410\ub2e4. \uadf8\ub798\ub3c4 \ub124 \ucde8\ud5a5\ub9cc \ub9de\uc740 \uac74 \uc544\ub2cc\uc9c0 \ud55c \ubc88 \ubcfc\ub798?","\ubc88 \uac74 \uae30\uc05c\ub370, \uc0ac\ub78c\ub4e4\uc774 \uacc4\uc18d \uc4f0\uace0 \uc2f6\uc5b4 \ud558\ub294\uc9c0\ub3c4 \uad81\uae08\ud574."],t.s)
