B.b9o=s(["\uadf8\ub54c \ub9c8\uc74c\uc5d0 \ub4e4\uc5c8\ub358 \uc774\uc720\ub791 \ub3c8\uc774 \ub420 \uac70\ub77c \ubcf8 \uc774\uc720\ub294 \uac19\uc558\uc5b4?","\uc0ac\ub78c\ub4e4\uc774 \uc2e4\uc81c\ub85c \uc4f0\ub294 \ubaa8\uc2b5\uae4c\uc9c0 \ubd24\ub294\uc9c0 \uc0dd\uac01\ud574 \ubcf4\uc790."],t.s)
B.aYb=s([B.b9C,B.b_W,B.aZp,B.b9o],t.rj)
B.b3I=s(["\ubbf8\uc548\ud558\ub2e4\uace0 \ub9d0\ud574 \uc900 \ub9c8\uc74c\uc740 \uc54c\uaca0\uc5b4.","\ub0b4\uac00 \ud55c \uc77c\uc774 \ub3c4\uc6c0\uc774 \ub410\ub2e4\ub2c8 \ub2e4\ud589\uc774\uc57c.","\uc9c0\uae08 \ub290\ub07c\ub294 \uac78 \uc5b5\uc9c0\ub85c \uc228\uae30\uc9c0 \uc54a\uc544\ub3c4 \ub3fc.","\uc6b0\ub9ac \ub458 \ub2e4 \ud3b8\ud55c \uacc4\ud68d\uc774\uba74 \uc88b\uaca0\uc5b4."],t.s)
B.aX7=s(["\uadf8 \ud68c\uc0ac \ubb3c\uac74, \uc368 \ubcf8 \uc0ac\ub78c\uc740 \ubb50\ub798?","\ub108\ub294 \uadf8 \ubb3c\uac74 \ub9c8\uc74c\uc5d0 \ub4e4\uc5c8\uc5b4?","\uc624\ub298\uc740 \uc5bc\ub9c8\uae4c\uc9c0 \uad1c\ucc2e\uc544?"],t.s)
